import{z as c,x as A,o as n,c as l,q as r,j as E,D as e,d as o,s as p,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"内容协商与压缩","description":"","frontmatter":{"title":"内容协商与压缩","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/content-negotiation.md","filePath":"cs/content-negotiation.md","lastUpdated":1791063341000}'),d={name:"cs/content-negotiation.md"};function B(g,a,C,h,m,D){const i=A("Mermaid");return n(),l("div",null,[a[2]||(a[2]=r('<h1 id="内容协商与压缩" tabindex="-1">内容协商与压缩 <a class="header-anchor" href="#内容协商与压缩" aria-label="Permalink to &quot;内容协商与压缩&quot;">​</a></h1><div class="epigraph"><p>Accept 头让客户端声明能懂的媒体类型、语言与编码；服务器挑表示，Content-Encoding 可 gzip，缓存必须 Vary。</p><footer>—— 据 RFC 9110 内容协商；RFC 9112 传输编码对照；RFC 1952 gzip 整理</footer></div><p><a href="/cs/cookies-sessions">上一课</a> 的头已影响缓存。主干<a href="/cs/http-semantics">缓存头</a> 未展开协商。缺口是 <strong>Accept* 与压缩</strong>：表示选择、<code>Vary</code>、与 chunked 的分工。本课不把 WebSocket 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一 URI 可有 JSON/HTML、中英、gzip/br。协商：客户端权重，服务器选或 406。压缩减带宽，CPU 换 \\(C\\) 上的头税；已加密的图片再 gzip 无益。<code>Content-Encoding</code> 是表示的一部分，<code>Transfer-Encoding</code> 是跳上的（1.1 chunked），H2/H3 不用 TE。中间缓存若忽略 <code>Vary: Accept-Encoding</code> 会把 gzip 给不能解的客户。</p><p>不要把压缩写成线路码 8B/10B。</p><p><span class="marginnote">Accept 族头就是客户端的「点菜单」：Accept 点格式（JSON 还是 HTML）、Accept-Language 点语言、Accept-Encoding 点压缩（gzip 还是 br），每项可带权重 q 值，如 gzip;q=0.8 表示「最好给 gzip，没有也行」。服务器照单挑一份最合适的表示。</span></p><p><span class="marginnote">RFC 9110 第 12 章。Brotli/zstd 是编码登记问题。本课不调压缩级别。</span></p><h3 id="压缩要-vary" tabindex="-1">压缩要 Vary <a class="header-anchor" href="#压缩要-vary" aria-label="Permalink to &quot;压缩要 Vary&quot;">​</a></h3><p>Accept 选表示；Content-Encoding 属表示，不是 1.1 的 TE。已压缩媒体再 gzip 无益。加密信道上压缩有历史风险。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：Accept → 选表示 → 可选压缩 → Vary。对照：传输层 TSO 不看媒体类型。与 PMTUD 无关直接，但压缩后长度变，影响是否分块。</p>',12)),(n(),E(s,null,{default:e(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22Accept%20%E6%97%8F%22%5D%20--%3E%20NEG%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%80%89%E6%8B%A9%22%5D%0A%20%20NEG%20--%3E%20CE%5B%22Content-Encoding%22%5D%0A%20%20CE%20--%3E%20VARY%5B%22%E7%BC%93%E5%AD%98%E6%8C%89%20Vary%20%E9%94%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"CDN 要按 Vary 键存多份，否则省的带宽变成错页。QUIC 0-RTT 的协商头也可重放。语言协商与 GeoDNS 后课可叠加。安全：压缩与加密同用有 CRIME 一类历史，TLS 上谨慎压缩。",-1)),a[5]||(a[5]=t("p",null,"chunked 与 gzip 常叠：先压缩再分块。",-1)),(n(),E(s,null,{default:e(()=>[p(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AFA%3A%20%E6%94%AF%E6%8C%81%20gzip%22%5D%20--%3E%20C%5B%22%E4%B8%AD%E9%97%B4%E7%BC%93%E5%AD%98%3A%20%E5%BF%BD%E7%95%A5%20Vary%22%5D%0A%20%20C%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%2C%20%E5%9B%9E%E6%BA%90%22%20--%3E%20O%5B%22%E6%BA%90%E7%AB%99%E8%BF%94%E5%9B%9E%20gzip%20%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20O%20--%3E%20C%0A%20%20C%20--%3E%20A%0A%20%20B%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AFB%3A%20%E4%B8%8D%E6%94%AF%E6%8C%81%20gzip%22%5D%20--%3E%20C%0A%20%20C%20--%20%22%E5%91%BD%E4%B8%AD%2C%20%E7%9B%B4%E6%8E%A5%E7%BB%99%E7%BC%93%E5%AD%98%E7%9A%84%20gzip%22%20--%3E%20B%0A%20%20B%20--%3E%20ERR%5B%22%E8%A7%A3%E4%B8%8D%E5%BC%80%2C%20%E9%A1%B5%E9%9D%A2%E4%B9%B1%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：一份 100 KB 的 HTML 经 gzip 常能压到 20-30 KB，省七成带宽，代价是两端各几毫秒 CPU；而 JPEG 已经压过，再 gzip 往往只省百分之一还白烧 CPU——压缩只对「还没压过的」内容划算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入内容编码登记的全部 IANA 表。WebSocket 是下一课。后课默认：协商选表示；压缩要 Vary。</p><p>强制只 gzip 而不看 Accept-Encoding 会破坏老客户。</p><p><span class="marginnote">常见误区：以为 Vary 只是建议性头。对缓存它是缓存键的一部分：Vary: Accept-Encoding 的意思是「gzip 版和原版各存一份，按请求头挑」。反过来，若写成 Vary: User-Agent，缓存会被切成每个浏览器版本一份，命中率几乎归零。</span></p><p>下一课<a href="/cs/websocket">WebSocket</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Accept 驱动表示选择。</li><li>Content-Encoding 属表示；要 Vary。</li><li>与 1.1 传输编码不是一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9110；gzip RFC 1952。</li></ul>',8))])}const T=c(d,[["render",B]]);export{f as __pageData,T as default};
